async function main(): Promise<void> {
  const p = new Proxy({ a: 1 } as Record<string, any>, { get: (t, k: string) => (k in t ? t[k] : "dflt"), has: () => true });
  console.log(p.a, p.q, "zz" in p);
  const px = new Proxy({ a: 1 } as any, { ownKeys: () => ["a", "z"], getOwnPropertyDescriptor: (t, k) => ({ value: t[k] ?? "zz", enumerable: true, configurable: true }) });
  console.log(Object.keys(px), { ...px });
  const rs = new ReadableStream({ start(c) { c.enqueue("w1"); c.enqueue("w2"); c.close(); } });
  const rd = rs.getReader();
  console.log(await rd.read(), await rd.read(), await rd.read());
}
